_captureManeuverActivity(entity) {
 const lease=entity&&this._maneuverActivityOwners.get(entity);
 const record=lease&&this._maneuverActivityRecords.get(lease);
 if(!record||!this._maneuverActivityCurrent(lease)) return null;
 return ()=>{
  if(this._maneuverActivityRecords.get(lease)!==record || getEntity(this.state,entity.id)!==entity || entity.occupantGeneration!==record.generation || entity.physicsBody!==record.body) return false;
  const ownsActivity=this._maneuverActivityOwners.get(entity)===lease && entity.data?.ai===record.ai && record.ai.activity===record.activity;
  this._cancelManeuverActivity(lease);
  if(ownsActivity&&record.onCapture){try{record.onCapture();}catch(_){return false;}}
  return true;
 };
}
